  'No anchor yet': { ar: 'لا يوجد مرسى بعد', pt: 'Ainda sem âncora', es: 'Aún sin ancla', de: 'Noch kein Anker', fr: 'Pas encore d\'ancre', it: 'Ancora nessuna ancora' },
  'Shown in the panic moment.': { ar: 'تظهر في لحظة الذعر.', pt: 'Aparece no momento de pânico.', es: 'Aparece en el momento de pánico.', de: 'Erscheint im Panikmoment.', fr: 'Elle apparaît dans le moment de panique.', it: 'Appare nel momento di panico.' },
