  'Import backup': { ar: 'استيراد نسخة احتياطية', pt: 'Importar backup', es: 'Importar copia', de: 'Sicherung importieren', fr: 'Importer une sauvegarde', it: 'Importa backup' },
  'Export CSV (spreadsheets)': { ar: 'تصدير CSV (جداول بيانات)', pt: 'Exportar CSV (planilhas)', es: 'Exportar CSV (hojas de cálculo)', de: 'CSV exportieren (Tabellen)', fr: 'Exporter CSV (tableurs)', it: 'Esporta CSV (fogli di calcolo)' },
  'Delete all data': { ar: 'حذف كل البيانات', pt: 'Apagar todos os dados', es: 'Borrar todos los datos', de: 'Alle Daten löschen', fr: 'Supprimer toutes les données', it: 'Elimina tutti i dati' },
